// Быстрая проверка TLS без AI. Нужна переменная NODE_FUNCTION_ALLOW_BUILTIN=tls
const tls = require('tls');

// Демо-список. Для боевого использования замените на свои домены.
const DOMAINS = [
  // 'expired.badssl.com',
  // 'self-signed.badssl.com',
  // 'wrong.host.badssl.com',
  // 'untrusted-root.badssl.com',
  'example.com',
];
const WARN_DAYS = 14;

function check(host) {
  return new Promise((resolve) => {
    let done = false;
    const finish = (r) => { if (!done) { done = true; resolve(r); } };
    const s = tls.connect(
      { host, port: 443, servername: host, rejectUnauthorized: false },
      () => {
        const c = s.getPeerCertificate();
        const r = {
          host,
          authorized: s.authorized,
          authError: s.authorizationError ? String(s.authorizationError) : null,
          issuer: (c.issuer && (c.issuer.O || c.issuer.CN)) || null,
          expires: c.valid_to,
          daysLeft: Math.floor((new Date(c.valid_to) - Date.now()) / 86400000),
        };
        s.end();
        finish(r);
      }
    );
    s.setTimeout(10000, () => { s.destroy(); finish({ host, error: 'timeout' }); });
    s.on('error', (e) => finish({ host, error: e.message }));
  });
}

const results = [];
for (const d of DOMAINS) results.push(await check(d));

const problems = [];
for (const r of results) {
  const findings = [];
  if (r.error) findings.push('Ошибка соединения: ' + r.error);
  else {
    if (r.daysLeft < 0) findings.push('Сертификат истёк ' + Math.abs(r.daysLeft) + ' дн. назад');
    else if (r.daysLeft <= WARN_DAYS) findings.push('Сертификат истекает через ' + r.daysLeft + ' дн.');
    if (!r.authorized) findings.push('Не проходит проверку: ' + r.authError);
  }
  if (findings.length) problems.push({ host: r.host, issuer: r.issuer || null, expires: r.expires || null, daysLeft: r.daysLeft ?? null, findings });
}

return [{ json: {
  checkedAt: new Date().toISOString(),
  total: results.length,
  healthy: results.length - problems.length,
  hasProblems: problems.length > 0,
  problems,
} }];

