const tls = require('tls');
const host = String(query).trim();
return await new Promise((resolve) => {
  let done = false;
  const finish = (o) => { if (!done) { done = true; resolve(JSON.stringify(o)); } };
  const s = tls.connect({ host, port: 443, servername: host, rejectUnauthorized: false }, () => {
    const c = s.getPeerCertificate();
    finish({
      host,
      authorized: s.authorized,
      authError: s.authorizationError ? String(s.authorizationError) : null,
      issuer: (c.issuer && (c.issuer.O || c.issuer.CN)) || null,
      subjectCN: c.subject && c.subject.CN,
      validFrom: c.valid_from,
      validTo: c.valid_to,
      daysLeft: Math.floor((new Date(c.valid_to) - Date.now()) / 86400000),
      fingerprint256: c.fingerprint256,
    });
    s.end();
  });
  s.setTimeout(10000, () => { s.destroy(); finish({ host, error: 'timeout' }); });
  s.on('error', (e) => finish({ host, error: e.message }));
});

const https = require('https');
function getJson(url, depth = 0) {
  return new Promise((resolve, reject) => {
    const req = https.get(url, { headers: { 'User-Agent': 'tls-watch/1.0', 'Accept': 'application/json' } }, (res) => {
      if (res.statusCode >= 300 && res.statusCode < 400 && res.headers.location && depth < 5) {
        res.resume();
        return resolve(getJson(res.headers.location, depth + 1));
      }
      let body = '';
      res.on('data', (c) => body += c);
      res.on('end', () => {
        if (res.statusCode !== 200) return reject(new Error('HTTP ' + res.statusCode));
        try { resolve(JSON.parse(body)); } catch (e) { reject(new Error('Невалидный JSON')); }
      });
    });
    req.setTimeout(20000, () => { req.destroy(); reject(new Error('timeout')); });
    req.on('error', reject);
  });
}

// query: основной домен, например "example.com"
const domain = String(query).trim();
try {
  const r = await getJson('https://rdap.org/domain/' + encodeURIComponent(domain));
  const ev = (r.events || []).find((e) => e.eventAction === 'expiration');
  if (!ev) return JSON.stringify({ domain, error: 'RDAP не вернул дату истечения' });
  return JSON.stringify({
    domain,
    expires: ev.eventDate,
    daysLeft: Math.floor((new Date(ev.eventDate) - Date.now()) / 86400000),
  });
} catch (e) {
  return JSON.stringify({ domain, error: 'RDAP недоступен: ' + e.message });
}

