// query: "host" или "host,hours" (по умолчанию 24 часа)
const parts = String(query).split(',');
const host = parts[0].trim();
const hours = parseInt(parts[1], 10) || 24;
const EXPECTED = ["Let's Encrypt", 'Google Trust Services'];
try {
  const rows = await getJson('https://crt.sh/?q=' + encodeURIComponent(host) + '&output=json');
  const since = Date.now() - hours * 3600000;
  const recent = rows.filter((r) => {
    const ts = r.entry_timestamp.endsWith('Z') ? r.entry_timestamp : r.entry_timestamp + 'Z';
    return new Date(ts).getTime() > since;
  });
  const unexpected = recent.filter((r) => !EXPECTED.some((i) => r.issuer_name.includes(i)));
  return JSON.stringify({
    host, windowHours: hours,
    recentCount: recent.length,
    unexpectedCount: unexpected.length,
    unexpectedIssuers: [...new Set(unexpected.map((r) => r.issuer_name))],
  });
} catch (e) {
  return JSON.stringify({ host, error: 'crt.sh недоступен: ' + e.message });
}
